try {
  if (window.location.hash && window.location.hash.startsWith('#/')) {
    var cleanRoute = window.location.hash.replace(/^#/?/, '/');
    if (window.history.replaceState) {
      window.history.replaceState(null, '', cleanRoute);
    }
  }
} catch(e) {}
